            }
        }

        foreach ($rows as [$kode, $bab, $nomor, $judul, $uraian, $aktif, $catatan, $inaktif, $keterangan, $keamanan]) {
            $uraian = filled($uraian) ? trim((string) $uraian) : trim((string) $judul);
            $aktifTahun = is_numeric($aktif) ? (int) $aktif : null;
            $catatanAktif = filled($catatan)
                ? trim((string) $catatan)
                : ($aktifTahun === null && filled($aktif) ? trim((string) $aktif) : null);

