                compact('kode', 'judul', 'uraian'),
                [
                    'bab' => $bab,
                    'nomor' => $nomor,
                    'masa_aktif_tahun' => $aktifTahun,
                    'masa_aktif_catatan' => $catatanAktif,
                    'masa_inaktif_tahun' => is_numeric($inaktif) ? (int) $inaktif : null,
